/* ФинМост 1.1. Интерактивные уроки и прозрачные учебные модели. */
(function(root,factory){
  if(typeof module==='object'&&module.exports)module.exports=factory();
  else root.FinMostLearning=factory();
})(typeof globalThis!=='undefined'?globalThis:this,function(){
  'use strict';
  const lessons={
    money:{title:'Зачем людям деньги',category:'Как устроены деньги',tag:'Основы',icon:'wallet',time:6,activity:'roles',
      desc:'Узнайте три функции денег и найдите их в повседневных решениях.',
      body:'<p>Представьте: вы чините велосипеды и хотите купить хлеб. При прямом обмене придётся найти пекаря, которому как раз нужен ремонт. Деньги позволяют продать свою работу одному человеку, а покупку сделать у другого.</p><p>У денег есть три основные функции: <b>средство обмена</b> — ими оплачивают товары и услуги; <b>мера стоимости</b> — в одной единице удобно сравнивать цены; <b>средство сбережения</b> — часть покупательной способности можно перенести в будущее. Инфляция способна уменьшать эту способность.</p><p>Деньги — не только монеты и купюры. Средства на банковском счёте тоже используются в расчётах. <b>Карта и QR-код — инструменты доступа к платежу, а не отдельная валюта.</b> Доверие к деньгам и надёжность расчётов помогают людям принимать их в обмен на свою работу.</p>',
      sources:[{title:'Банк Англии: что такое деньги',url:'https://www.bankofengland.co.uk/explainers/what-is-money'},{title:'Банк Англии: деньги в современной экономике',url:'https://www.bankofengland.co.uk/quarterly-bulletin/2014/q1/money-in-the-modern-economy-an-introduction'}],
      questions:[
        {q:'Вы сравнили два ноутбука по цене в рублях. Какая функция денег здесь главная?',a:['Мера стоимости','Средство обмена','Гарантия доходности'],c:0,e:'Общая единица позволяет сравнивать цены разных товаров. Покупка ещё не совершена.'},
        {q:'Что верно про банковскую карту?',a:['Это новая валюта','Она даёт доступ к средствам и операциям по счёту','Каждая карта создаёт отдельные деньги'],c:1,e:'Карта — платёжный инструмент. Деньги учитываются на счёте; сама пластиковая карта не является валютой.'},
        {q:'Почему 1 000 ₽ через несколько лет могут купить меньше товаров?',a:['Номинал купюры автоматически уменьшится','Любое сбережение обязательно исчезает','Из-за роста цен снижается покупательная способность'],c:2,e:'При росте цен номинальная сумма может оставаться той же, а доступное количество товаров — уменьшаться.'}]
    },
    history:{title:'История денег: что менялось',category:'Как устроены деньги',tag:'История',icon:'clock',time:7,activity:'timeline',
      desc:'Соберите хронологию и отделите форму денег от способа платежа.',
      body:'<p>История денег — не одна лестница, одинаковая для всех стран. Товарные деньги, монеты, записи о долгах, бумажные знаки и безналичные расчёты могли сосуществовать. Менялись удобство, способы проверки подлинности и доверие к тому, кто выпустил деньги.</p><p><b>Четыре ориентира:</b> в VII веке до н. э. в Лидии чеканили одни из самых ранних монет. В Британском музее хранится китайский бумажный денежный знак, датированный 1375 годом — это пример уже существовавших бумажных денег, а не дата их изобретения. В России ассигнации появились в 1769 году. Система быстрых платежей начала действовать 28 января 2019 года.</p><p>СБП — способ переводить деньги, а не новая валюта. Быстрая оплата по QR-коду не отменяет проверки получателя. Новая технология меняет удобство платежа, но не делает любое предложение безопасным.</p>',
      sources:[{title:'Банк России: монеты Лидии',url:'https://www.cbr.ru/press/regevent/?id=17394'},{title:'Британский музей: китайский денежный знак 1375 года',url:'https://www.britishmuseum.org/collection/object/C_CIB-EA-260'},{title:'Библиотека Банка России: ассигнации 1769 года',url:'https://library.cbr.ru/catalog/lib/books/424565/'},{title:'Банк России: запуск СБП в 2019 году',url:'https://cbr.ru/press/event/?id=2377'}],
      questions:[
        {q:'Что появилось в России в 1769 году?',a:['СБП','Ассигнации — первые российские бумажные деньги','Первые в мире монеты'],c:1,e:'Ассигнации появились в России в 1769 году. Это не дата появления бумажных денег во всём мире.'},
        {q:'Чем запуск СБП отличается от появления новой валюты?',a:['СБП — платёжная инфраструктура для переводов','Все рубли заменили на баллы','Банкноты перестали существовать'],c:0,e:'СБП меняет способ перевода. Рубль остаётся денежной единицей, а наличные и другие способы расчётов продолжают существовать.'},
        {q:'Какой вывод об истории денег точнее?',a:['У всех стран была одна последовательность без исключений','Каждая новая форма мгновенно уничтожала старую','Разные формы денег и способы расчётов могли сосуществовать'],c:2,e:'Хронология отдельных примеров не описывает единственный путь всех обществ. Наличные и безналичные расчёты сосуществуют и сейчас.'}]
    },
    economy:{title:'Куда идут деньги в экономике',category:'Как устроены деньги',tag:'Экономика',icon:'briefcase',time:7,activity:'flows',
      desc:'Проведите четыре платежа и проследите связь покупок, труда и бизнеса.',
      body:'<p>Покупка — часть цепочки. Домохозяйство получает товар, а бизнес — выручку. Из поступивших средств предприятие оплачивает материалы, труд, налоги и другие обязательства. Выручка при этом не равна прибыли: часть денег нужна для расходов.</p><p>Зарплата одного человека становится его доходом и источником будущих покупок. Налоги поступают в бюджет, из которого финансируют общественные задачи. Поставщики получают оплату за свои товары и услуги. <b>Денежный поток помогает увидеть связи между участниками экономики.</b></p><p>Ниже — наша упрощённая модель с четырьмя участниками и вымышленными суммами. В ней есть только переводы: общая сумма не меняется. В реальной экономике существуют кредит, эмиссия и внешние платежи, поэтому этот результат нельзя переносить на всю денежную систему. В частности, банковское кредитование может создавать новые средства на счетах; возможности банков ограничены правилами, рисками и денежно-кредитной политикой.</p>',
      model:'Суммы придуманы для урока. Платёж 100 ₽ в бюджет не обозначает действующую налоговую ставку. Модель не рассчитывает прибыль или налоговые обязательства.',
      sources:[{title:'Банк Англии: создание денег в современной экономике',url:'https://www.bankofengland.co.uk/quarterly-bulletin/2014/q1/money-creation-in-the-modern-economy'}],
      questions:[
        {q:'Пекарня получила 1 000 ₽ от покупателя. Можно ли считать всю сумму прибылью?',a:['Да, любая выручка — прибыль','Нет: нужно учесть связанные расходы и обязательства','Да, если деньги пришли по карте'],c:1,e:'Выручка — поступления от продажи. Для расчёта прибыли нужно учесть расходы; способ оплаты этого не меняет.'},
        {q:'В учебной модели после четырёх переводов общая сумма сохранилась. Почему?',a:['Так всегда устроена вся денежная масса страны','Налоги исчезают из денежной системы','В этой модели были только переводы между её участниками'],c:2,e:'Это свойство заданной закрытой модели. В ней не было создания денег, погашения банковского кредита или внешних операций.'},
        {q:'За что домохозяйство получает зарплату от предприятия?',a:['За предоставленный труд','За сам факт хранения купюр','За каждую просмотренную цену'],c:0,e:'Зарплата — оплата труда. В модели её получатель затем может использовать доход для покупок и сбережений.'}]
    },
    inflation:{title:'Сумма та же. А покупок меньше?',category:'Как устроены деньги',tag:'Инфляция',icon:'chart',time:6,activity:'prices',
      desc:'Измените рост цен и сбережений и сравните покупательную способность.',
      body:'<p><b>Инфляция — устойчивый рост общего уровня цен.</b> Отдельный товар при этом может дорожать, дешеветь или не менять цену. Снижение инфляции означает более медленный рост цен, а не обязательно их падение.</p><p>Номинальная сумма — сколько рублей у вас есть. Покупательная способность — сколько товаров и услуг на них можно получить. Если корзина стоила 1 000 ₽ и подорожала на 10%, она стоит 1 100 ₽. За неизменные 10 000 ₽ получится купить уже около 9,09 таких корзин вместо 10.</p><p>В лаборатории сравните рост сбережений с ростом цен. За несколько лет оба показателя накапливаются: стоимость корзины = 1 000 × (1 + рост цен)<sup>лет</sup>. Покупательная способность суммы в сегодняшних рублях = будущая сумма / (1 + рост цен)<sup>лет</sup>. Это точное соотношение в заданной модели, а не простое вычитание процентов.</p>',
      model:'Начальные сбережения 10 000 ₽; корзина 1 000 ₽. Годовые темпы постоянны; прирост сбережений начисляется раз в год. Пополнений, снятий, комиссий и налогов нет. Значения учебные, не прогноз и не банковское предложение.',
      sources:[{title:'Банк России: что такое инфляция',url:'https://www.cbr.ru/dkp/about_inflation/'},{title:'Банк России: вопросы об инфляции',url:'https://cbr.ru/faq/dkp/02/'}],
      questions:[
        {q:'Корзина стоила 1 000 ₽, рост цен за год — 10%. Новая цена?',a:['1 010 ₽','1 100 ₽','900 ₽'],c:1,e:'1 000 × 1,10 = 1 100 ₽. За те же деньги можно купить меньше таких корзин.'},
        {q:'Рост цен снизился с 10% до 5% в год. Что это означает само по себе?',a:['Цены в целом растут медленнее','Все цены упали на 5%','Все товары стали стоить как год назад'],c:0,e:'Положительная инфляция означает рост общего уровня цен. Меньший положительный темп — более медленный рост, а не дефляция.'},
        {q:'Сбережения за год выросли на 5%, а учебная корзина — на 10%. Что с покупательной способностью?',a:['Она обязательно выросла на 5%','Не изменилась, ведь рублей больше','Уменьшилась: 1,05 / 1,10 меньше единицы'],c:2,e:'Номинальная сумма выросла, но отстала от цены корзины. В модели её покупательная способность снизилась примерно на 4,55%.'}]
    }
  };
  const roleOptions=['Средство обмена','Мера стоимости','Средство сбережения'];
  const roleRounds=[
    {text:'Вы заплатили 150 ₽ за поездку. Какую функцию денег показывает именно оплата?',correct:0,explanation:'Деньги передали в обмен на услугу. Это средство обмена.'},
    {text:'До покупки вы сравнили аренду велосипедов: 200 ₽ и 300 ₽ за час. Какая функция помогает сравнить предложения?',correct:1,explanation:'Цены выражены в одной денежной единице. Здесь деньги служат мерой стоимости.'},
    {text:'Часть заработанного вы сохранили на будущую покупку. Какая функция здесь главная?',correct:2,explanation:'Покупку отложили, сохранив деньги. Это средство сбережения; реальная покупательная способность всё ещё зависит от цен.'}
  ];
  const timeline=[
    {id:'coins',title:'Лидийские монеты',date:'VII век до н. э.',text:'Одни из ранних монет. Стандартизация и проверка подлинности облегчают расчёты.'},
    {id:'china',title:'Китайский бумажный денежный знак',date:'1375 год',text:'Датировка музейного экспоната, а не изобретения бумажных денег. Бумагу легче перевозить, чем тяжёлые монеты.'},
    {id:'russia',title:'Ассигнации в России',date:'1769 год',text:'Появление первых российских бумажных денег. Важны подлинность и доверие к выпустившему их учреждению.'},
    {id:'sbp',title:'Запуск СБП',date:'2019 год',text:'Развитие платёжной инфраструктуры. Меняется способ перевода рублей, а не сама валюта.'}
  ];
  const flowAccounts={people:5000,bakery:2000,supplier:1000,public:0};
  const accountNames={people:'Домохозяйство',bakery:'Пекарня',supplier:'Поставщик',public:'Бюджет'};
  const flowSteps=[
    {from:'people',to:'bakery',amount:1000,text:'Домохозяйство покупает выпечку на 1 000 ₽. Кому перечислить оплату?',explanation:'Покупатель получил товар, пекарня — выручку. Деньги и товар движутся в противоположных направлениях.'},
    {from:'bakery',to:'supplier',amount:300,text:'Пекарня оплачивает муку на 300 ₽. Кто получает деньги?',explanation:'Поставщик получает оплату за материалы. Из выручки бизнеса нужно покрывать затраты.'},
    {from:'bakery',to:'people',amount:500,text:'Пекарня выплачивает 500 ₽ за труд члену домохозяйства. Кто получает зарплату?',explanation:'Оплата труда стала доходом домохозяйства. Эти деньги можно направить на покупки или сбережения.'},
    {from:'bakery',to:'public',amount:100,text:'Пекарня перечисляет условный платёж 100 ₽ на общественные нужды. Куда идут деньги?',explanation:'Деньги поступили в бюджет. В этом упражнении сумма задана, а не рассчитана по налоговым правилам.'}
  ];
  function finite(n,name,min,max){
    if(typeof n!=='number'||!Number.isFinite(n)||n<min||n>max)throw new Error('Некорректное значение: '+name);
    return n;
  }
  function purchasingPower(principal,inflation,growth,years){
    finite(principal,'начальная сумма',0,1e9);finite(inflation,'рост цен',0,25);finite(growth,'рост сбережений',0,25);finite(years,'срок',1,10);
    if(!Number.isInteger(years))throw new Error('Срок должен быть целым числом лет');
    const priceFactor=(1+inflation/100)**years;
    const nominal=principal*(1+growth/100)**years;
    const real=nominal/priceFactor;
    return {nominal,real,basket:1000*priceFactor,baskets:real/1000,change:principal?((real/principal)-1)*100:0};
  }
  function applyFlow(accounts,stepIndex,recipient){
    if(!Number.isInteger(stepIndex)||!flowSteps[stepIndex])throw new Error('Неизвестный шаг');
    const step=flowSteps[stepIndex];
    if(recipient!==step.to)throw new Error('Выберите получателя по смыслу операции');
    const result={};
    for(const id of Object.keys(flowAccounts))result[id]=finite(accounts[id],id,0,1e9);
    if(result[step.from]<step.amount)throw new Error('Недостаточно средств');
    result[step.from]-=step.amount;result[step.to]+=step.amount;
    return result;
  }
  function timelineCorrect(order){return Array.isArray(order)&&order.length===timeline.length&&order.every((id,i)=>id===timeline[i].id);}
  return {lessons,roleOptions,roleRounds,timeline,flowAccounts,accountNames,flowSteps,purchasingPower,applyFlow,timelineCorrect};
});
